# Completa la línea marcada y compruébala con py check.
def acuerdo(pares):
    # cada par: [puntuación de a, puntuación de b, elección de la persona («a» o «b»)]
    aciertos = 0
    for pa, pb, humano in pares:
        elige = "a" if pa > pb else "b"
        aciertos += 0   # ← cambia esta línea: suma 1 si elige coincide con humano
    return aciertos / len(pares)

print(acuerdo([[2.0, 1.0, "a"], [0.5, 3.0, "a"]]))   # 0.5
